function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 500) return 'grid needs 1 to 500 rows.';
  const cols = Array.isArray(grid[0]) ? grid[0].length : 0;
  if (cols < 1 || cols > 500) return 'grid needs 1 to 500 columns.';
  let starts = 0, targets = 0, free = 0;
  for (const line of grid) {
    if (!Array.isArray(line) || line.length !== cols) return 'Every row of grid must have the same length.';
    for (const v of line) {
      if (v !== -1 && v !== 0 && v !== 1 && v !== 2) return 'Each cell is -1 (start), 0 (blocked), 1 (open) or 2 (target).';
      if (v === -1) starts++;
      if (v === 2) targets++;
      if (v !== 0) free++;
    }
  }
  if (starts !== 1) return 'grid needs exactly one start cell (-1).';
  if (targets !== 1) return 'grid needs exactly one target cell (2).';
  if (free > 1500) return 'The local judge supports at most 1,500 cells that are not blocked.';
  return null;
}

