function adapt(input, solve, kit) {
  const [grid] = input;
  const rows = grid.length;
  const cols = grid[0].length;
  let row = grid.findIndex(line => line.includes(-1));
  let col = grid[row].indexOf(-1);
  const steps = { U: [-1, 0], D: [1, 0], L: [0, -1], R: [0, 1] };
  const limit = 100 * rows * cols + 1000;
  let calls = 0;
  const count = () => {
    calls++;
    if (calls > limit) throw new Error('The solution made too many calls to master; visit each cell only a few times.');
  };
  const neighbour = (direction) => {
    if (!Object.hasOwn(steps, direction)) throw new Error(`Unknown direction ${JSON.stringify(direction)}: use 'U', 'D', 'L' or 'R'.`);
    const r = row + steps[direction][0], c = col + steps[direction][1];
    return r >= 0 && r < rows && c >= 0 && c < cols && grid[r][c] !== 0 ? [r, c] : null;
  };
  // The grid and the robot's position stay inside this closure; the solution only sees these three methods.
  const master = Object.freeze({
    canMove(direction) {
      count();
      return neighbour(direction) !== null;
    },
    move(direction) {
      count();
      const cell = neighbour(direction);
      if (cell) [row, col] = cell;
    },
    isTarget() {
      count();
      return grid[row][col] === 2;
    }
  });
  return solve(master);
}

