function findShortestPath(master) {
  const moves = [['U', -1, 0, 'D'], ['D', 1, 0, 'U'], ['L', 0, -1, 'R'], ['R', 0, 1, 'L']];
  const open = new Set(['0,0']);
  let target = null;

  function explore(row, col) {
    if (master.isTarget()) {
      target = `${row},${col}`;
    }
    for (const [dir, dr, dc, back] of moves) {
      const key = `${row + dr},${col + dc}`;
      if (!open.has(key) && master.canMove(dir)) {
        open.add(key);
        master.move(dir);
        explore(row + dr, col + dc);
        master.move(back);
      }
    }
  }

  explore(0, 0);
  if (target === null) {
    return -1;
  }
  const queue = [[0, 0]];
  const dist = new Map([['0,0', 0]]);
  for (let head = 0; head < queue.length; head++) {
    const [row, col] = queue[head];
    const key = `${row},${col}`;
    if (key === target) {
      return dist.get(key);
    }
    for (const [, dr, dc] of moves) {
      const next = `${row + dr},${col + dc}`;
      if (open.has(next) && !dist.has(next)) {
        dist.set(next, dist.get(key) + 1);
        queue.push([row + dr, col + dc]);
      }
    }
  }
  return -1;
}

