function findShortestPath(master) {
  // Map the reachable cells with an explicit stack of the moves taken (no recursion), then find distances
  // by relaxing every cell from its neighbours until nothing changes.
  const step = { U: [-1, 0], D: [1, 0], L: [0, -1], R: [0, 1] };
  const opposite = { U: 'D', D: 'U', L: 'R', R: 'L' };
  const cells = new Map([['0,0', master.isTarget()]]);
  const path = [];
  let r = 0, c = 0;
  for (;;) {
    let moved = false;
    for (const d of 'RLDU') {
      const key = (r + step[d][0]) + ',' + (c + step[d][1]);
      if (cells.has(key) || !master.canMove(d)) continue;
      master.move(d);
      r += step[d][0];
      c += step[d][1];
      cells.set(key, master.isTarget());
      path.push(d);
      moved = true;
      break;
    }
    if (moved) continue;
    if (!path.length) break;
    const back = opposite[path.pop()];
    master.move(back);
    r += step[back][0];
    c += step[back][1];
  }
  const dist = new Map([...cells.keys()].map(key => [key, key === '0,0' ? 0 : Infinity]));
  for (let changed = true; changed;) {
    changed = false;
    for (const key of cells.keys()) {
      const [kr, kc] = key.split(',').map(Number);
      for (const [dr, dc] of Object.values(step)) {
        const other = (kr + dr) + ',' + (kc + dc);
        if (dist.has(other) && dist.get(other) + 1 < dist.get(key)) {
          dist.set(key, dist.get(other) + 1);
          changed = true;
        }
      }
    }
  }
  for (const [key, isTarget] of cells) if (isTarget) return dist.get(key);
  return -1;
}

