function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const dirs = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  if (size !== 'large') {
    let m = 1 + pick(6), n = 1 + pick(6);
    if (m * n < 2) n = 2;
    const wallRate = [0, 0.2, 0.35, 0.5][pick(4)];
    const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => (rand() < wallRate ? 0 : 1)));
    const start = pick(m * n);
    let target = pick(m * n - 1);
    if (target >= start) target++;
    grid[Math.floor(start / n)][start % n] = -1;
    grid[Math.floor(target / n)][target % n] = 2;
    return [grid];
  }
  // Carve a maze-like open region (mostly a tree, with a few loops) of at most 1,450 cells in a 100 x 100 grid.
  const m = 100, n = 100;
  const grid = Array.from({ length: m }, () => new Array(n).fill(0));
  const inside = (r, c) => r >= 0 && r < m && c >= 0 && c < n;
  const sr = pick(m), sc = pick(n);
  grid[sr][sc] = 1;
  const cells = [[sr, sc]];
  const cap = 1000 + pick(450);
  const loopRate = [0, 0.05, 0.2][pick(3)];
  for (let tries = 0; cells.length < cap && tries < 300000; tries++) {
    const [r, c] = rand() < 0.7 ? cells[cells.length - 1 - pick(Math.min(8, cells.length))] : cells[pick(cells.length)];
    const [dr, dc] = dirs[pick(4)];
    const nr = r + dr, nc = c + dc;
    if (!inside(nr, nc) || grid[nr][nc] !== 0) continue;
    const touching = dirs.filter(([a, b]) => inside(nr + a, nc + b) && grid[nr + a][nc + b] !== 0).length;
    if (touching > 1 && rand() >= loopRate) continue;
    grid[nr][nc] = 1;
    cells.push([nr, nc]);
  }
  grid[sr][sc] = -1;
  if (rand() < 0.85) {
    const [tr, tc] = cells[1 + pick(cells.length - 1)];
    grid[tr][tc] = 2;
    return [grid];
  }
  // Otherwise hide the target in a blocked pocket that touches no open cell, so the answer is -1.
  for (;;) {
    const tr = pick(m), tc = pick(n);
    if (grid[tr][tc] === 0 && dirs.every(([a, b]) => !inside(tr + a, tc + b) || grid[tr + a][tc + b] === 0)) {
      grid[tr][tc] = 2;
      return [grid];
    }
  }
}
